// Marks the page so the test can see this inline script ran.
    document.body.dataset.inlineScript = 'ran';
    // Inline script: fill in the year and say whether the shop is open right now.
    document.querySelectorAll('.year').forEach((el) => {
      el.textContent = String(new Date().getFullYear());
    });
    (function () {
      const now = new Date();
      const day = now.getDay();
      const hour = now.getHours() + now.getMinutes() / 60;
      const open = day >= 2 && day <= 6 && hour >= 9 && hour < 17.5;
      const status = document.getElementById('open-status');
      if (status) {
        status.textContent += open ? ' We are open right now.' : ' We are closed right now.';
      }
    })();

